# Jumbo worker bootstrap, generated by the Jumbo desktop app for one session.
# The ticket holds only public data. The gist token comes from the Kaggle Secret JUMBO_GIST_TOKEN.
import base64
import hashlib
import json
import os
import pathlib
import stat
import subprocess
import sys
import tomllib
import urllib.request

TICKET = json.loads(base64.b64decode("__TICKET__").decode())
BUNDLE = json.loads(base64.b64decode("__BUNDLE__").decode())
HOME = pathlib.Path(os.environ.get("JUMBO_HOME", "/kaggle/working/jumbo"))
# Pinned release; the download is verified against the checksum Cloudflare publishes for it.
CLOUDFLARED_VERSION = "2026.10.0"
CLOUDFLARED_URL = f"https://github.com/cloudflare/cloudflared/releases/download/{CLOUDFLARED_VERSION}/cloudflared-linux-amd64"
CLOUDFLARED_SHA256 = "d33ff2d14475178d2012c2c56beba87389ac5ded27649519f198a7d3134a99db"


def unpack() -> pathlib.Path:
    src = HOME / "src"
    for rel, text in BUNDLE.items():
        path = src / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    (HOME / "ticket.json").write_text(json.dumps(TICKET), encoding="utf-8")
    return src


def install(src: pathlib.Path) -> None:
    # The worker's own dependencies plus the model extras (Magi etc.) that only run on Kaggle.
    project = tomllib.loads((src / "pyproject.toml").read_text())["project"]
    deps = project["dependencies"] + project.get("optional-dependencies", {}).get("models", [])
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", *deps], check=True)


def cloudflared() -> str:
    target = HOME / f"cloudflared-{CLOUDFLARED_VERSION}"
    if not target.exists():
        partial = target.with_name(target.name + ".partial")
        urllib.request.urlretrieve(CLOUDFLARED_URL, partial)
        digest = hashlib.sha256(partial.read_bytes()).hexdigest()
        if digest != CLOUDFLARED_SHA256:
            partial.unlink()
            raise SystemExit(f"cloudflared {CLOUDFLARED_VERSION} failed checksum verification ({digest})")
        partial.chmod(partial.stat().st_mode | stat.S_IEXEC)
        partial.rename(target)
    return str(target)


def main() -> int:
    src = unpack()
    print(f"jumbo: session {TICKET['session_id']}, worker unpacked to {src}", flush=True)
    if os.environ.get("JUMBO_DRY_RUN"):
        return 0
    install(src)
    env = {**os.environ, "PYTHONPATH": str(src)}
    command = [sys.executable, "-m", "jumbo_worker", "--ticket", str(HOME / "ticket.json"), "--data", str(HOME / "data"), "--cloudflared", cloudflared()]
    return subprocess.call(command, env=env)


sys.exit(main())
